BEGIN READ ONLY;
SET LOCAL standard_conforming_strings=on;
SET LOCAL search_path=pg_catalog;
SET LOCAL row_security=off;
SELECT jsonb_build_object(
'inventory', COALESCE(((SELECT encode(sha256(convert_to(string_agg(id::text||chr(9)||word||chr(9)||type::text||chr(9)||rarity_level::text||chr(10),'' ORDER BY id),'UTF8')),'hex') FROM public.words)='0d69e5c92a45c52e85afe6fd903388009d408ebda54bb97c1d9818c0672f6fc0' AND (SELECT count(*) FROM public.words)=77698),false),
'ledger_empty', COALESCE(((SELECT count(*)=0 FROM classificator_private.human_correction_receipts)),false),
'revisions_complete_unique', COALESCE(((SELECT count(*)=count(classificator_revision) AND count(*)=count(DISTINCT classificator_revision) AND min(classificator_revision)>0 FROM public.words)),false),
'revision_trigger', COALESCE((EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid='public.words'::regclass AND t.tgname='classificator_word_revision' AND t.tgenabled='A' AND t.tgtype=23 AND p.prosecdef AND p.proconfig=ARRAY['search_path=pg_catalog'] AND btrim(p.prosrc,E' \n\r\t')='BEGIN
    NEW.classificator_revision := pg_catalog.nextval(''classificator_private.words_revision_seq''::pg_catalog.regclass);
    RETURN NEW;
END;')),false),
'role_disabled_and_bounded', COALESCE((EXISTS (SELECT 1 FROM pg_roles WHERE rolname='classificator_human_executor' AND NOT rolcanlogin AND rolbypassrls AND NOT rolsuper AND NOT rolinherit AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication)),false),
'role_no_untrusted_memberships', COALESCE((NOT EXISTS (SELECT 1 FROM pg_auth_members WHERE (roleid='classificator_human_executor'::regrole OR member='classificator_human_executor'::regrole) AND NOT (roleid='classificator_human_executor'::regrole AND member='postgres'::regrole AND admin_option AND NOT inherit_option AND NOT set_option))),false),
'executor_grants', COALESCE((has_schema_privilege('classificator_human_executor','classificator_private','USAGE') AND has_table_privilege('classificator_human_executor','public.words','SELECT') AND has_table_privilege('classificator_human_executor','public.words','UPDATE') AND NOT has_table_privilege('classificator_human_executor','public.words','INSERT') AND NOT has_table_privilege('classificator_human_executor','public.words','DELETE') AND has_table_privilege('classificator_human_executor','classificator_private.words_revision_contract','SELECT') AND NOT has_table_privilege('classificator_human_executor','classificator_private.words_revision_contract','UPDATE') AND NOT has_sequence_privilege('classificator_human_executor','classificator_private.words_revision_seq','USAGE') AND NOT has_sequence_privilege('classificator_human_executor','classificator_private.words_revision_seq','UPDATE')),false),
'revision_sequence', COALESCE((EXISTS (SELECT 1 FROM pg_sequence WHERE seqrelid='classificator_private.words_revision_seq'::regclass AND seqtypid='bigint'::regtype AND seqincrement=1 AND seqmin=1 AND seqcache=1 AND NOT seqcycle)),false),
'rls_unchanged', COALESCE(((SELECT relrowsecurity=true AND relforcerowsecurity=false FROM pg_class WHERE oid='public.words'::regclass)),false),
'policies_unchanged', COALESCE(((SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY policyname),'[]'::jsonb) FROM pg_policies p WHERE schemaname='public' AND tablename='words')='[{"cmd": "SELECT", "qual": "true", "roles": ["public"], "tablename": "words", "permissive": "PERMISSIVE", "policyname": "Enable read access for all users", "schemaname": "public", "with_check": null}]'::jsonb),false),
'word_grants_preserved', COALESCE(((SELECT coalesce(jsonb_agg(a::text ORDER BY a::text),'[]'::jsonb) FROM pg_class c CROSS JOIN LATERAL unnest(c.relacl) a WHERE c.oid='public.words'::regclass AND split_part(a::text,'=',1)<>'classificator_human_executor')='["anon=r/postgres", "postgres=arwdDxtm/postgres", "service_role=arwdDxtm/postgres"]'::jsonb),false),
'ddl_hooks_unchanged', COALESCE(((SELECT coalesce(jsonb_object_agg(t.evtname,jsonb_build_object('event',t.evtevent,'enabled',t.evtenabled,'tags',t.evttags,'owner',pg_get_userbyid(t.evtowner),'security_definer',p.prosecdef,'definition',pg_get_functiondef(p.oid))),'{}'::jsonb) FROM pg_event_trigger t JOIN pg_proc p ON p.oid=t.evtfoid)='{"ensure_rls": {"tags": ["CREATE TABLE", "CREATE TABLE AS", "SELECT INTO"], "event": "ddl_command_end", "owner": "postgres", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION public.rls_auto_enable()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE\n  cmd record;\nBEGIN\n  FOR cmd IN\n    SELECT *\n    FROM pg_event_trigger_ddl_commands()\n    WHERE command_tag IN (''CREATE TABLE'', ''CREATE TABLE AS'', ''SELECT INTO'')\n      AND object_type IN (''table'',''partitioned table'')\n  LOOP\n     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN (''public'') AND cmd.schema_name NOT IN (''pg_catalog'',''information_schema'') AND cmd.schema_name NOT LIKE ''pg_toast%'' AND cmd.schema_name NOT LIKE ''pg_temp%'' THEN\n      BEGIN\n        EXECUTE format(''alter table if exists %s enable row level security'', cmd.object_identity);\n        RAISE LOG ''rls_auto_enable: enabled RLS on %'', cmd.object_identity;\n      EXCEPTION\n        WHEN OTHERS THEN\n          RAISE LOG ''rls_auto_enable: failed to enable RLS on %'', cmd.object_identity;\n      END;\n     ELSE\n        RAISE LOG ''rls_auto_enable: skip % (either system schema or not in enforced list: %.)'', cmd.object_identity, cmd.schema_name;\n     END IF;\n  END LOOP;\nEND;\n$function$\n", "security_definer": false}, "issue_pg_graphql_access": {"tags": ["CREATE FUNCTION"], "event": "ddl_command_end", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION extensions.grant_pg_graphql_access()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nbegin\n    if not exists (\n        select 1\n        from pg_catalog.pg_event_trigger_ddl_commands() ev\n        join pg_catalog.pg_extension e on ev.objid = e.oid\n        where e.extname = ''pg_graphql''\n    ) then\n        return;\n    end if;\n\n    drop function if exists graphql_public.graphql;\n    create or replace function graphql_public.graphql(\n        \"operationName\" text default null,\n        query text default null,\n        variables jsonb default null,\n        extensions jsonb default null\n    )\n        returns jsonb\n        language sql\n    as $$\n        select graphql.resolve(\n            query := query,\n            variables := coalesce(variables, ''{}''),\n            \"operationName\" := \"operationName\",\n            extensions := extensions\n        );\n    $$;\n\n    -- Attach the wrapper to the extension so DROP EXTENSION cascades to it,\n    -- which in turn triggers set_graphql_placeholder to reinstall the \"not enabled\" stub.\n    alter extension pg_graphql add function graphql_public.graphql(text, text, jsonb, jsonb);\n\n    grant usage on schema graphql to postgres, anon, authenticated, service_role;\n    grant execute on function graphql.resolve to postgres, anon, authenticated, service_role;\n    grant usage on schema graphql to postgres with grant option;\n    grant usage on schema graphql_public to postgres with grant option;\nend;\n$function$\n", "security_definer": false}, "issue_graphql_placeholder": {"tags": ["DROP EXTENSION"], "event": "sql_drop", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION extensions.set_graphql_placeholder()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\n    DECLARE\n    graphql_is_dropped bool;\n    BEGIN\n    graphql_is_dropped = (\n        SELECT ev.schema_name = ''graphql_public''\n        FROM pg_event_trigger_dropped_objects() AS ev\n        WHERE ev.schema_name = ''graphql_public''\n    );\n\n    IF graphql_is_dropped\n    THEN\n        create or replace function graphql_public.graphql(\n            \"operationName\" text default null,\n            query text default null,\n            variables jsonb default null,\n            extensions jsonb default null\n        )\n            returns jsonb\n            language plpgsql\n            set search_path to ''''\n        as $$\n            DECLARE\n                server_version float;\n            BEGIN\n                server_version = (SELECT (SPLIT_PART((select version()), '' '', 2))::float);\n\n                IF server_version >= 14 THEN\n                    RETURN jsonb_build_object(\n                        ''errors'', jsonb_build_array(\n                            jsonb_build_object(\n                                ''message'', ''pg_graphql extension is not enabled.''\n                            )\n                        )\n                    );\n                ELSE\n                    RETURN jsonb_build_object(\n                        ''errors'', jsonb_build_array(\n                            jsonb_build_object(\n                                ''message'', ''pg_graphql is only available on projects running Postgres 14 onwards.''\n                            )\n                        )\n                    );\n                END IF;\n            END;\n        $$;\n    END IF;\n\n    END;\n$function$\n", "security_definer": false}, "pgrst_ddl_watch": {"tags": null, "event": "ddl_command_end", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION extensions.pgrst_ddl_watch()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nDECLARE\n  cmd record;\nBEGIN\n  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    IF cmd.command_tag IN (\n      ''CREATE SCHEMA'', ''ALTER SCHEMA''\n    , ''CREATE TABLE'', ''CREATE TABLE AS'', ''SELECT INTO'', ''ALTER TABLE''\n    , ''CREATE FOREIGN TABLE'', ''ALTER FOREIGN TABLE''\n    , ''CREATE VIEW'', ''ALTER VIEW''\n    , ''CREATE MATERIALIZED VIEW'', ''ALTER MATERIALIZED VIEW''\n    , ''CREATE FUNCTION'', ''ALTER FUNCTION''\n    , ''CREATE TRIGGER''\n    , ''CREATE TYPE'', ''ALTER TYPE''\n    , ''CREATE RULE''\n    , ''COMMENT''\n    )\n    -- don''t notify in case of CREATE TEMP table or other objects created on pg_temp\n    AND cmd.schema_name is distinct from ''pg_temp''\n    THEN\n      NOTIFY pgrst, ''reload schema'';\n    END IF;\n  END LOOP;\nEND; $function$\n", "security_definer": false}, "pgrst_drop_watch": {"tags": null, "event": "sql_drop", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION extensions.pgrst_drop_watch()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nDECLARE\n  obj record;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()\n  LOOP\n    IF obj.object_type IN (\n      ''schema''\n    , ''table''\n    , ''foreign table''\n    , ''view''\n    , ''materialized view''\n    , ''function''\n    , ''trigger''\n    , ''type''\n    , ''rule''\n    )\n    AND obj.is_temporary IS false -- no pg_temp objects\n    THEN\n      NOTIFY pgrst, ''reload schema'';\n    END IF;\n  END LOOP;\nEND; $function$\n", "security_definer": false}, "graphql_watch_ddl": {"tags": null, "event": "ddl_command_end", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION graphql.increment_schema_version()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nbegin\n    perform pg_catalog.nextval(''graphql.seq_schema_version'');\nend;\n$function$\n", "security_definer": true}, "graphql_watch_drop": {"tags": null, "event": "sql_drop", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION graphql.increment_schema_version()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nbegin\n    perform pg_catalog.nextval(''graphql.seq_schema_version'');\nend;\n$function$\n", "security_definer": true}, "issue_pg_cron_access": {"tags": ["CREATE EXTENSION"], "event": "ddl_command_end", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION extensions.grant_pg_cron_access()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nBEGIN\n  IF EXISTS (\n    SELECT\n    FROM pg_event_trigger_ddl_commands() AS ev\n    JOIN pg_extension AS ext\n    ON ev.objid = ext.oid\n    WHERE ext.extname = ''pg_cron''\n  )\n  THEN\n    grant usage on schema cron to postgres with grant option;\n\n    alter default privileges in schema cron grant all on tables to postgres with grant option;\n    alter default privileges in schema cron grant all on functions to postgres with grant option;\n    alter default privileges in schema cron grant all on sequences to postgres with grant option;\n\n    alter default privileges for user supabase_admin in schema cron grant all\n        on sequences to postgres with grant option;\n    alter default privileges for user supabase_admin in schema cron grant all\n        on tables to postgres with grant option;\n    alter default privileges for user supabase_admin in schema cron grant all\n        on functions to postgres with grant option;\n\n    grant all privileges on all tables in schema cron to postgres with grant option;\n    revoke all on table cron.job from postgres;\n    grant select on table cron.job to postgres with grant option;\n    revoke trigger on cron.job_run_details from postgres;\n  END IF;\nEND;\n$function$\n", "security_definer": false}, "issue_pg_net_access": {"tags": ["CREATE EXTENSION"], "event": "ddl_command_end", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION extensions.grant_pg_net_access()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM pg_event_trigger_ddl_commands() AS ev\n    JOIN pg_extension AS ext\n    ON ev.objid = ext.oid\n    WHERE ext.extname = ''pg_net''\n  )\n  THEN\n    IF NOT EXISTS (\n      SELECT 1\n      FROM pg_roles\n      WHERE rolname = ''supabase_functions_admin''\n    )\n    THEN\n      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;\n    END IF;\n\n    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;\n\n    IF EXISTS (\n      SELECT FROM pg_extension\n      WHERE extname = ''pg_net''\n      -- all versions in use on existing projects as of 2025-02-20\n      -- version 0.12.0 onwards don''t need these applied\n      AND extversion IN (''0.2'', ''0.6'', ''0.7'', ''0.7.1'', ''0.8.0'', ''0.10.0'', ''0.11.0'')\n    ) THEN\n      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;\n      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;\n\n      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;\n      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;\n\n      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;\n      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;\n\n      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;\n      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;\n    END IF;\n  END IF;\nEND;\n$function$\n", "security_definer": false}}'::jsonb),false),
'ledger_grants', COALESCE((has_table_privilege('classificator_human_executor','classificator_private.human_correction_receipts','SELECT') AND has_table_privilege('classificator_human_executor','classificator_private.human_correction_receipts','INSERT') AND has_table_privilege('classificator_human_executor','classificator_private.human_correction_receipts','UPDATE') AND NOT has_table_privilege('classificator_human_executor','classificator_private.human_correction_receipts','DELETE') AND NOT has_table_privilege('classificator_human_executor','classificator_private.human_correction_receipts','TRUNCATE')),false),
'api_roles_denied', COALESCE((NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role','authenticator') AND has_schema_privilege(oid,'classificator_private','USAGE')) AND NOT EXISTS (SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl) a WHERE n.nspname='classificator_private' AND a.grantee=0)),false),
'installation_receipt_bound', COALESCE((EXISTS (SELECT 1 FROM classificator_private.installation_receipt i CROSS JOIN classificator_private.words_revision_contract c WHERE i.singleton AND c.singleton AND i.receipt->>'package_id'='600ee91fc220c2f0ec88f821916da535d7f4388e2de922395b6ee61ccf2f6fa1' AND i.receipt->>'epoch'=c.epoch::text AND i.receipt->>'inventory_sha256'='0d69e5c92a45c52e85afe6fd903388009d408ebda54bb97c1d9818c0672f6fc0' AND i.receipt->>'corrections_applied'='false')),false),
'existing_data_preserved', COALESCE((EXISTS (SELECT 1 FROM classificator_private.installation_receipt WHERE receipt->>'version'='human-installation-bundle-v1' AND receipt->>'data_before'=receipt->>'data_after' AND receipt->>'data_after'=(SELECT encode(sha256(convert_to(string_agg((to_jsonb(w)-'classificator_revision')::text, E'\n' ORDER BY id),'UTF8')),'hex') FROM public.words w))),false)
) AS checks;
ROLLBACK;
